dashboard.definition:
{
  "title": "2 · Auditor Evidence (Studio)",
  "description": "Who touched the database, when, and what did they run?",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-15d@d,now"
      }
    },
    "input_src": {
      "type": "input.dropdown",
      "title": "Data source",
      "options": {
        "token": "src",
        "defaultValue": "index=teleport_demo",
        "items": [
          {
            "label": "Demo data (synthetic, 15 days)",
            "value": "index=teleport_demo"
          },
          {
            "label": "Live lab data",
            "value": "index=teleport"
          },
          {
            "label": "Both",
            "value": "(index=teleport OR index=teleport_demo)"
          }
        ]
      }
    },
    "input_who": {
      "type": "input.text",
      "title": "Identity (name or *)",
      "options": {
        "token": "who",
        "defaultValue": "*"
      }
    },
    "input_res": {
      "type": "input.text",
      "title": "Database (name or *)",
      "options": {
        "token": "res",
        "defaultValue": "*"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    },
    "tokens": {
      "default": {
        "who": {
          "value": "*"
        },
        "res": {
          "value": "*"
        }
      }
    }
  },
  "dataSources": {
    "ds_base": {
      "type": "ds.search",
      "options": {
        "query": "$src$ sourcetype=teleport:audit\n| eval actor=coalesce(user, 'identity.user', user_name, \"unknown\")\n| eval actor_type=case(like(actor,\"bot-%\"),\"machine\", actor=\"system\",\"system\", like(actor,\"%.localhost\"),\"system\", true(),\"human\")\n| eval actor_class=case(actor_type=\"human\",\"human\", match(actor,\"^bot-(claude|copilot|lab)\"),\"ai_agent\", actor_type=\"machine\",\"workload\", true(),\"system\")\n| eval outcome=if(success=\"false\" OR like(code,\"%W\"),\"denied\",\"allowed\")\n| eval src=coalesce('addr.remote','identity.client_ip')\n| eval src_ip=replace(src,\":\\d+$$\",\"\")\n| eval resource=coalesce(db_service, app_name, server_hostname, kubernetes_cluster)\n| eval hour_utc=floor((_time%86400)/3600)\n| eval ttl_h=if(event=\"cert.create\", round((strptime(substr('identity.expires',1,19).\"+0000\",\"%Y-%m-%dT%H:%M:%S%z\")-_time)/3600,2), null())\n| eval is_write=if(event=\"db.session.query\" AND match(db_query,\"(?i)^\\s*(create|drop|alter|insert|update|delete|truncate|grant)\"),1,0)\n| fields _time, event, code, user, success, error, method, mfa_device, name, roles, login, sid, uid, db_service, db_name, db_user, db_query, app_name, server_hostname, kubernetes_cluster, verb, request_path, response_code, bot_name, user_name, \"identity.user\", \"identity.roles{}\", \"identity.expires\", \"identity.client_ip\", \"addr.remote\", demo, actor, actor_type, actor_class, outcome, src, src_ip, resource, hour_utc, ttl_h, is_write",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      },
      "name": "base"
    },
    "ds_db": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base",
        "query": "| search event IN (\"db.session.start\",\"db.session.query\",\"db.session.end\") resource=\"$res$\" actor=\"$who$\""
      }
    },
    "k1": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| eventstats count(eval(event=\"db.session.start\" AND outcome=\"allowed\")) as total | timechart span=1d count(eval(event=\"db.session.start\" AND outcome=\"allowed\")) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "k2": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| search event=\"db.session.start\" outcome=\"allowed\" | stats dc(actor) as ids"
      }
    },
    "k3": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| eventstats count(eval(event=\"db.session.query\")) as total | timechart span=1d count(eval(event=\"db.session.query\")) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "k4": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| eventstats count(eval(event=\"db.session.start\" AND outcome=\"denied\")) as total | timechart span=1d count(eval(event=\"db.session.start\" AND outcome=\"denied\")) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "k5": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| eventstats count(eval(is_write=1)) as total | timechart span=1d count(eval(is_write=1)) as events, first(total) as total | eventstats max(total) as total"
      }
    },
    "t1": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| stats count(eval(event=\"db.session.start\" AND outcome=\"allowed\")) as sessions, count(eval(event=\"db.session.query\")) as queries, sum(is_write) as write_attempts, dc(db_user) as db_users, min(_time) as first_seen, max(_time) as last_seen by actor, actor_class | eval first_seen=strftime(first_seen,\"%Y-%m-%d %H:%M\"), last_seen=strftime(last_seen,\"%Y-%m-%d %H:%M\") | sort - queries"
      }
    },
    "c1": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| search event=\"db.session.query\" | timechart span=1d count by actor limit=8 useother=f"
      }
    },
    "c2": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| search event=\"db.session.start\" | eval hr=printf(\"%02d\",hour_utc) | chart count over hr by actor_class"
      }
    },
    "t2": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_db",
        "query": "| search event=\"db.session.query\" | eval kind=if(is_write=1,\"WRITE\",\"read\") | sort - _time | eval time=strftime(_time,\"%Y-%m-%d %H:%M:%S\") | table time actor db_user kind db_query sid uid"
      }
    }
  },
  "visualizations": {
    "v_k1": {
      "type": "splunk.singlevalue",
      "title": "DATABASE SESSIONS",
      "dataSources": {
        "primary": "k1"
      },
      "options": {
        "majorColor": "#4E9BE0",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#4E9BE0",
        "sparklineAreaColor": "#4E9BE0",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      }
    },
    "v_k2": {
      "type": "splunk.singlevalue",
      "title": "IDENTITIES THAT CONNECTED",
      "dataSources": {
        "primary": "k2"
      },
      "options": {
        "majorColor": "#3FB6B6",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      }
    },
    "v_k3": {
      "type": "splunk.singlevalue",
      "title": "QUERIES ON RECORD",
      "dataSources": {
        "primary": "k3"
      },
      "options": {
        "majorColor": "#B07CE8",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#B07CE8",
        "sparklineAreaColor": "#B07CE8",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      }
    },
    "v_k4": {
      "type": "splunk.singlevalue",
      "title": "CONNECTIONS DENIED",
      "dataSources": {
        "primary": "k4"
      },
      "options": {
        "majorColor": "> majorValue | rangeValue(majorColorCfg)",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3FB68B",
        "sparklineAreaColor": "#3FB68B",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      },
      "context": {
        "majorColorCfg": [
          {
            "to": 1,
            "value": "#3FB68B"
          },
          {
            "from": 1,
            "value": "#E5534B"
          }
        ]
      }
    },
    "v_k5": {
      "type": "splunk.singlevalue",
      "title": "WRITE ATTEMPTS",
      "dataSources": {
        "primary": "k5"
      },
      "options": {
        "majorColor": "> majorValue | rangeValue(majorColorCfg)",
        "sparklineDisplay": "below",
        "trendDisplay": "off",
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValues": "> primary | seriesByName('events')",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3FB68B",
        "sparklineAreaColor": "#3FB68B",
        "backgroundColor": "#141B27",
        "majorFontSize": 56
      },
      "context": {
        "majorColorCfg": [
          {
            "to": 1,
            "value": "#3FB68B"
          },
          {
            "from": 1,
            "value": "#F0A030"
          }
        ]
      }
    },
    "v_t1": {
      "type": "splunk.table",
      "title": "Who accessed the database",
      "dataSources": {
        "primary": "t1"
      },
      "options": {
        "count": 8,
        "backgroundColor": "#141B27",
        "dataOverlayMode": "none",
        "showRowNumbers": false,
        "wrap": true,
        "columnFormat": {
          "actor_class": {
            "rowBackgroundColors": "> table | seriesByName(\"actor_class\") | matchValue(actor_classBg)"
          }
        }
      },
      "context": {
        "actor_classBg": [
          {
            "match": "human",
            "value": "#1F4E79"
          },
          {
            "match": "ai_agent",
            "value": "#5B3A8C"
          },
          {
            "match": "workload",
            "value": "#1F6B6B"
          },
          {
            "match": "system",
            "value": "#3A4352"
          }
        ]
      }
    },
    "v_c1": {
      "type": "splunk.column",
      "title": "Queries per day, by identity",
      "dataSources": {
        "primary": "c1"
      },
      "options": {
        "backgroundColor": "#141B27",
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      }
    },
    "v_c2": {
      "type": "splunk.column",
      "title": "When is the database used? (UTC hour, by identity class)",
      "dataSources": {
        "primary": "c2"
      },
      "options": {
        "backgroundColor": "#141B27",
        "legendDisplay": "bottom",
        "stackMode": "stacked",
        "seriesColorsByField": {
          "human": "#4E9BE0",
          "ai_agent": "#B07CE8",
          "workload": "#3FB6B6",
          "system": "#7A8699"
        }
      }
    },
    "v_q": {
      "type": "splunk.markdown",
      "options": {
        "backgroundColor": "#141B27",
        "fontColor": "#E6EDF7",
        "markdown": "### Questions an auditor asks, and where the answer lives\n- **Who accessed it?** The \"Who accessed the database\" table\n- **What did they run?** The query log below, with a unique event ID (uid)\n- **Was it allowed?** Connections denied, and Security Watch\n- **Was the credential short-lived?** Trust Scorecard\n- **Can I export it?** Use Export on any panel\n\n*This supports evidence for access-control and logging requirements (for example C5, KRITIS, DORA). It does not certify compliance by itself.*"
      }
    },
    "v_t2": {
      "type": "splunk.table",
      "title": "Full query log (the evidence trail)",
      "dataSources": {
        "primary": "t2"
      },
      "options": {
        "count": 8,
        "backgroundColor": "#141B27",
        "dataOverlayMode": "none",
        "showRowNumbers": false,
        "wrap": true,
        "columnFormat": {
          "kind": {
            "rowBackgroundColors": "> table | seriesByName(\"kind\") | matchValue(kindBg)"
          }
        }
      },
      "context": {
        "kindBg": [
          {
            "match": "WRITE",
            "value": "#7A5A1A"
          },
          {
            "match": "read",
            "value": "#1F4E3A"
          }
        ]
      }
    },
    "v_l1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## ①  Who touched the database, and how often",
        "fontColor": "#4E9BE0",
        "backgroundColor": "transparent"
      }
    },
    "v_l2": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## ②  When it is used, and what the auditor can ask",
        "fontColor": "#F0A030",
        "backgroundColor": "transparent"
      }
    },
    "v_l3": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "## ③  The evidence trail: every query, with its event ID",
        "fontColor": "#3FB68B",
        "backgroundColor": "transparent"
      }
    },
    "v_bar": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#3FB6B6",
        "strokeColor": "#3FB6B6",
        "rx": 4
      }
    },
    "v_h1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Scene 2: auditor evidence. Who touched the database, when, and what did they run?",
        "fontColor": "#FFFFFF",
        "backgroundColor": "transparent"
      }
    },
    "v_h2": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Every answer comes from the Teleport audit log, tied to an identity and a unique event ID.",
        "fontColor": "#9FB3CC",
        "backgroundColor": "transparent"
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1920,
      "height": 1680,
      "display": "auto-scale",
      "backgroundColor": "#0B0F17"
    },
    "structure": [
      {
        "item": "v_bar",
        "type": "block",
        "position": {
          "x": 40,
          "y": 30,
          "w": 10,
          "h": 86
        }
      },
      {
        "item": "v_h1",
        "type": "block",
        "position": {
          "x": 68,
          "y": 24,
          "w": 1750,
          "h": 56
        }
      },
      {
        "item": "v_h2",
        "type": "block",
        "position": {
          "x": 68,
          "y": 82,
          "w": 1750,
          "h": 34
        }
      },
      {
        "item": "v_k1",
        "type": "block",
        "position": {
          "x": 40,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k2",
        "type": "block",
        "position": {
          "x": 412,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k3",
        "type": "block",
        "position": {
          "x": 784,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k4",
        "type": "block",
        "position": {
          "x": 1156,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_k5",
        "type": "block",
        "position": {
          "x": 1528,
          "y": 140,
          "w": 350,
          "h": 190
        }
      },
      {
        "item": "v_l1",
        "type": "block",
        "position": {
          "x": 40,
          "y": 350,
          "w": 1840,
          "h": 36
        }
      },
      {
        "item": "v_l2",
        "type": "block",
        "position": {
          "x": 40,
