        }
      },
      {
        "item": "v_l3",
        "type": "block",
        "position": {
          "x": 40,
          "y": 1210,
          "w": 1840,
          "h": 36
        }
      },
      {
        "item": "v_t1",
        "type": "block",
        "position": {
          "x": 40,
          "y": 392,
          "w": 1000,
          "h": 380
        }
      },
      {
        "item": "v_c1",
        "type": "block",
        "position": {
          "x": 1062,
          "y": 392,
          "w": 818,
          "h": 380
        }
      },
      {
        "item": "v_c2",
        "type": "block",
        "position": {
          "x": 40,
          "y": 842,
          "w": 700,
          "h": 340
        }
      },
      {
        "item": "v_q",
        "type": "block",
        "position": {
          "x": 762,
          "y": 842,
